import json, numpy as np
p=np.load('p_fit1.npy')
XL,mq,kiv,kpv,mp,TPf,TQf,TVf=[float(x) for x in p]
sub={
 "params":{"XL":XL,"mq":mq,"kiv":kiv,"kpv":kpv,"mp":mp,"TPf":TPf,"TQf":TQf,"TVf":TVf,"w0":2*np.pi*60,"Pref":None},
 "defs":{
   "Er":"V0 + XL*Q0/V0",
   "Ei":"XL*P0/V0",
   "E0":"sqrt(Er**2 + Ei**2)",
   "Vc":"Vset + mq*(Q0 - Qm)",
   "Ee":"min(max(kpv*(Vc - Vm) + xv, 0.0), 1.5)",
   "s":"d - theta"
 },
 "states":{
   "Pm":{"rhs":"(P - Pm)/TPf","init":"P0"},
   "Qm":{"rhs":"(Q - Qm)/TQf","init":"Q0"},
   "Vm":{"rhs":"(V - Vm)/TVf","init":"V0"},
   "xv":{"rhs":"kiv*(Vc - Vm)","init":"E0"},
   "d":{"rhs":"w0*mp*(P0 - Pm)","init":"theta0 + atan2(Ei, Er)"}
 },
 "outputs":{"P":"Ee*V*sin(s)/XL","Q":"(Ee*V*cos(s) - V**2)/XL"}
}
del sub["params"]["Pref"]
json.dump(sub,open('submission.json','w'),indent=1)
print(open('submission.json').read()[:400])
